; Character animation
; $782a-$7957

; Copies one byte row of the Rockford characters $4C, $4D, $5C and $5D. Input: X = frame offset, Y = byte row 0-7. Walking uses the left or right frames. Standing uses the standing image, with random eye blinks and foot taps.
animate_rockford
        lda joystick_dir
        cmp #$0f
        beq animate_rockford_idle
        lda #$00
        sta rockford_tap
        sta rockford_blink
        lda rockford_facing
        bne animate_rockford_left
        lda rockford_right_tl,x
        sta gfx_rockford_tl,y
        lda rockford_right_tr,x
        sta gfx_rockford_tr,y
        lda rockford_right_bl,x
        sta gfx_rockford_bl,y
        lda rockford_right_br,x
        sta gfx_rockford_br,y
        rts
animate_rockford_left
        lda rockford_left_tl,x
        sta gfx_rockford_tl,y
        lda rockford_left_tr,x
        sta gfx_rockford_tr,y
        lda rockford_left_bl,x
        sta gfx_rockford_bl,y
        lda rockford_left_br,x
        sta gfx_rockford_br,y
        rts
; Once in each cycle, Rockford blinks with a chance of 1 in 4. The foot tap toggles with a chance of 1 in 16.
animate_rockford_idle
        cpx #$00
        bne animate_rockford_top
        lda #$00
        sta rockford_blink
        jsr random_from_timers
        and #$03
        bne animate_rockford_tap_check
        lda #$01
        sta rockford_blink
animate_rockford_tap_check
        jsr random_from_timers
        and #$0f
        bne animate_rockford_top
        lda #$01
        eor rockford_tap
        sta rockford_tap
animate_rockford_top
        lda rockford_blink
        beq animate_rockford_top_stand
        lda rockford_blink_tl,x
        sta gfx_rockford_tl,y
        lda rockford_blink_tr,x
        sta gfx_rockford_tr,y
        jmp animate_rockford_bottom
animate_rockford_top_stand
        lda gfx_rockford_stand_tl,y
        sta gfx_rockford_tl,y
        lda gfx_rockford_stand_tr,y
        sta gfx_rockford_tr,y
animate_rockford_bottom
        lda rockford_tap
        beq animate_rockford_bot_stand
        lda rockford_tap_bl,x
        sta gfx_rockford_bl,y
        lda rockford_tap_br,x
        sta gfx_rockford_br,y
        rts
animate_rockford_bot_stand
        lda gfx_rockford_stand_bl,y
        sta gfx_rockford_bl,y
        lda gfx_rockford_stand_br,y
        sta gfx_rockford_br,y
        rts
; Shows the status line during play. Then copies the current animation frame (anim_frame) into the characters of the diamond and of Rockford. Also the amoeba, the butterfly and the firefly characters, as cave_anim_flags selects.
animate_chars
        lda birth_countdown
        bne animate_chars_start
        lda cave_clock_on
        beq animate_chars_start
        jsr show_game_status_line
animate_chars_start
        lda anim_frame
        asl
        tax
        ldy #$00
animate_chars_loop
        lda diamond_glyph_tl,x
        sta gfx_diamond_tl,y
        lda diamond_glyph_tr,x
        sta gfx_diamond_tr,y
        lda diamond_glyph_bl,x
        sta gfx_diamond_bl,y
        lda diamond_glyph_br,x
        sta gfx_diamond_br,y
        lda cave_anim_flags
        beq animate_chars_next
        cmp #$04                        ; Bit 2: amoeba (characters $40, $41, $50, $51).
        bcc animate_chars_butterfly
        lda amoeba_glyph_tl,x
        sta gfx_amoeba_tl,y
        lda amoeba_glyph_tr,x
        sta gfx_amoeba_tr,y
        lda amoeba_glyph_bl,x
        sta gfx_amoeba_bl,y
        lda amoeba_glyph_br,x
        sta gfx_amoeba_br,y
animate_chars_butterfly
        lda cave_anim_flags
        and #$02
        beq animate_chars_firefly
        lda butterfly_glyph_tl,x
        sta gfx_butterfly_tl,y
        lda butterfly_glyph_tr,x
        sta gfx_butterfly_tr,y
        lda butterfly_glyph_bl,x
        sta gfx_butterfly_bl,y
        lda butterfly_glyph_br,x
        sta gfx_butterfly_br,y
animate_chars_firefly
        lda cave_anim_flags
        and #$01
        beq animate_chars_next
        lda firefly_glyph_tl,x
        sta gfx_firefly_tl,y
        lda firefly_glyph_tr,x
        sta gfx_firefly_tr,y
        lda firefly_glyph_bl,x
        sta gfx_firefly_bl,y
        lda firefly_glyph_br,x
        sta gfx_firefly_br,y
animate_chars_next
        jsr animate_rockford
        inx
        iny
        cpy #$08
        bne animate_chars_loop
        rts
